--font-sans: var(--font-geist-sans), system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
--font-mono: var(--font-geist-mono), "Fira Code", "Cascadia Code", ui-monospace, monospace;

/* ──────────────────────────────────────────────────────────
   TYPOGRAPHY SCALE — semantic names
────────────────────────────────────────────────────────── */
--text-display-size:    2.25rem;  /* 36px */
--text-display-height:  2.5rem;   /* 40px */
--text-display-weight:  700;
--text-display-track:   -0.02em;

--text-h1-size:    1.75rem;       /* 28px */
--text-h1-height:  2rem;          /* 32px */
--text-h1-weight:  700;
--text-h1-track:   -0.015em;

--text-h2-size:    1.25rem;       /* 20px */
--text-h2-height:  1.75rem;       /* 28px */
--text-h2-weight:  600;
--text-h2-track:   -0.01em;

--text-h3-size:    1rem;          /* 16px */
--text-h3-height:  1.5rem;        /* 24px */
--text-h3-weight:  600;
--text-h3-track:   -0.005em;

--text-body-size:    0.875rem;    /* 14px */
--text-body-height:  1.25rem;     /* 20px */
--text-body-weight:  400;
--text-body-track:   0em;

--text-body-sm-size:    0.8125rem; /* 13px */
--text-body-sm-height:  1.125rem;  /* 18px */
--text-body-sm-weight:  400;
--text-body-sm-track:   0em;

--text-caption-size:    0.75rem;  /* 12px */
--text-caption-height:  1rem;     /* 16px */
--text-caption-weight:  400;
--text-caption-track:   0em;

--text-micro-size:    0.625rem;   /* 10px */
--text-micro-height:  0.875rem;   /* 14px */
--text-micro-weight:  500;
--text-micro-track:   0.06em;     /* uppercase tracking */

/* ──────────────────────────────────────────────────────────
   SPACING CONSTANTS — semantic aliases
────────────────────────────────────────────────────────── */
--spacing-page-x:      1.5rem;   /* px-6 — desktop page horizontal padding */
--spacing-page-x-sm:   1rem;     /* px-4 — mobile page horizontal padding */
--spacing-page-y:      1.5rem;   /* py-6 — vertical section gap */
--spacing-card-pad:    1.5rem;   /* p-6  — card internal padding */
--spacing-card-gap:    1rem;     /* gap-4 — gap between cards in a grid */
--spacing-section-gap: 1.5rem;   /* space-y-6 — between page sections */
--spacing-field-gap:   1rem;     /* space-y-4 — between form fields */

/* ──────────────────────────────────────────────────────────
   ICON SIZE SCALE — reference constants (see lib/design-tokens.ts)
────────────────────────────────────────────────────────── */
--icon-xs:  0.75rem;   /* 12px */
--icon-sm:  0.875rem;  /* 14px */
--icon-md:  1rem;      /* 16px */
--icon-lg:  1.25rem;   /* 20px */
--icon-xl:  1.5rem;    /* 24px */
--icon-2xl: 2rem;      /* 32px */

/* ──────────────────────────────────────────────────────────
   SIDEBAR TOKENS (shadcn sidebar primitives)
────────────────────────────────────────────────────────── */

/* Medium depth for drawers, modals */
--shadow-soft-md: 0 4px 16px -4px oklch(13% 0.015 264 / 0.10), 0 2px 8px -2px oklch(13% 0.015 264 / 0.07);

/* Floating elements — command palette, toasts, tooltips */
--shadow-lift: 0 8px 24px -4px oklch(13% 0.015 264 / 0.14),
               0 4px 10px -2px oklch(13% 0.015 264 / 0.08);

/* Full-screen overlays — modal backdrop shadow on dialog */
--shadow-overlay: 0 24px 64px -12px oklch(13% 0.015 264 / 0.22),
                  0 8px 24px -4px oklch(13% 0.015 264 / 0.12);

/* ──────────────────────────────────────────────────────────
   RADIUS
────────────────────────────────────────────────────────── */

--radius: 0.5rem;
--radius-sm: 0.25rem;
--radius-md: 0.5rem;
--radius-lg: 0.75rem;
--radius-xl: 1rem;
--radius-2xl: 1.5rem;   /* 24px — large modals, full-bleed cards */
--radius-full: 9999px;  /* pill buttons, avatar chips, progress bars */

--shadow-soft:    0 1px 2px 0 oklch(0% 0 0 / 0.25), 0 1px 3px 0 oklch(0% 0 0 / 0.18);
--shadow-soft-md: 0 4px 16px -4px oklch(0% 0 0 / 0.35), 0 2px 8px -2px oklch(0% 0 0 / 0.22);
--shadow-lift:    0 8px 24px -4px oklch(0% 0 0 / 0.50), 0 4px 10px -2px oklch(0% 0 0 / 0.30);
--shadow-overlay: 0 24px 64px -12px oklch(0% 0 0 / 0.65), 0 8px 24px -4px oklch(0% 0 0 / 0.40);
--shadow-card: 0 1px 3px 0 oklch(0% 0 0 / 0.3), 0 1px 2px -1px oklch(0% 0 0 / 0.2);
--shadow-card-hover: 0 4px 12px -2px oklch(0% 0 0 / 0.4), 0 2px 6px -2px oklch(0% 0 0 / 0.3);
--sidebar: oklch(14.5% 0.014 264);

