// lib/design-tokens.ts
// Typed design token constants — Vega owns this file.
// Koda consumes; never edits structure.

export const iconSize = {
  xs:  'size-3',    // 12px — inline decorative, tiny badges
  sm:  'size-3.5',  // 14px — dense table cells, caption row
  md:  'size-4',    // 16px — default — buttons, form inputs
  lg:  'size-5',    // 20px — card headers, navigation items
  xl:  'size-6',    // 24px — empty state icons (small variant)
