    className:
      'text-[length:var(--text-h3-size)] leading-[var(--text-h3-height)] font-[number:var(--text-h3-weight)] tracking-[var(--text-h3-track)]',
  },
  body: {
    defaultTag: 'p' as const,
    className:
      'text-[length:var(--text-body-size)] leading-[var(--text-body-height)]',
  },
  'body-sm': {
    defaultTag: 'p' as const,
