      'text-[length:var(--text-body-sm-size)] leading-[var(--text-body-sm-height)]',
  },
  caption: {
    defaultTag: 'p' as const,
    className:
      'text-[length:var(--text-caption-size)] leading-[var(--text-caption-height)] text-muted-foreground',
  },
  micro: {
    defaultTag: 'span' as const,
    className:
      'text-[length:var(--text-micro-size)] leading-[var(--text-micro-height)] font-[number:var(--text-micro-weight)] tracking-[var(--text-micro-track)] uppercase',
  },
} as const

type TypographyVariant = keyof typeof variantConfig

interface TypographyProps {
  variant: TypographyVariant
  as?: ElementType
  className?: string
  children: ReactNode
  id?: string
  tabIndex?: number
}

export function Typography({
  variant,
  as,
  className,
  children,
  ...rest
}: TypographyProps) {
  const config = variantConfig[variant]
  const Tag = (as ?? config.defaultTag) as ElementType
  return (
    <Tag className={cn(config.className, className)} {...rest}>
      {children}
    </Tag>
  )
}

