'use client'

import type { LucideIcon } from 'lucide-react'
import { TrendingUp, TrendingDown, AlertCircle } from 'lucide-react'
import Link from 'next/link'
import { cn } from '@/lib/utils'
import { Skeleton } from '@/components/ui/skeleton'
import { Sparkline } from '@/components/ui/sparkline'

interface KpiCardProps {
  label: string
  value: string | number
  /** Formatted delta string e.g. "+12.4%" or "-3.1%" */
  delta?: string
  /** Direction of delta — controls badge color */
  trend?: 'up' | 'down' | 'neutral'
  /** When true, "down" is good (e.g. churn rate) */
  invertTrend?: boolean
  /** Supporting text shown below delta (e.g. "vs last month") */
  subtextLabel?: string
  /** Sparkline data — array of numbers (last N periods) */
  sparkline?: number[]
  icon?: LucideIcon
  /** Card-level accent color — use a CSS token reference, not raw hex */
  accentVar?: string  // e.g. 'var(--color-primary)'
  href?: string       // makes the entire card a link
  loading?: boolean
  error?: boolean
  /** Stagger animation delay in ms */
  index?: number
}

function TrendBadge({
  delta,
  trend,
  invertTrend,
  subtextLabel,
}: {
  delta: string
  trend: 'up' | 'down' | 'neutral'
  invertTrend: boolean
  subtextLabel?: string
}) {
  const isPositive = invertTrend ? trend === 'down' : trend === 'up'
  const isNeutral = trend === 'neutral'

  if (isNeutral) {
    return (
      <div className="mt-2.5 flex items-center gap-1.5">
        <span className="text-[11px] text-muted-foreground">{delta}</span>
        {subtextLabel && <span className="text-[11px] text-muted-foreground">{subtextLabel}</span>}
      </div>
    )
  }

  return (
    <div className="mt-2.5 flex items-center gap-1.5">
      <span
        className={cn(
          'inline-flex items-center gap-0.5 rounded-full px-1.5 py-0.5 text-[11px] font-semibold',
          isPositive
            ? 'bg-emerald-50 text-emerald-700 dark:bg-emerald-500/15 dark:text-emerald-400'
            : 'bg-red-50 text-red-700 dark:bg-red-500/15 dark:text-red-400',
        )}
      >
        {isPositive ? (
          <TrendingUp className="h-3 w-3" aria-hidden="true" />
        ) : (
          <TrendingDown className="h-3 w-3" aria-hidden="true" />
        )}
        {delta}
      </span>
      {subtextLabel && (
        <span className="text-[11px] text-muted-foreground">{subtextLabel}</span>
      )}
    </div>
  )
}

export function KpiCard({
  label,
  value,
  delta,
  trend = 'neutral',
  invertTrend = false,
  subtextLabel,
  sparkline,
  icon: Icon,
  accentVar = 'var(--color-primary)',
  href,
  loading = false,
  error = false,
  index = 0,
}: KpiCardProps) {
  const cardContent = (
    <div
      className={cn(
        'group relative overflow-hidden rounded-xl bg-card',
        'border border-border',
        'shadow-[var(--shadow-card)]',
        'transition-all duration-150 ease-out',
        href && 'hover:shadow-[var(--shadow-card-hover)] hover:-translate-y-px cursor-pointer',
        'animate-fade-in-up p-5',
      )}
      style={{
        animationDelay: `${index * 60}ms`,
        animationFillMode: 'both',
        ['--kpi-accent' as string]: accentVar,
      }}
    >
      {/* Left accent bar (3px, full height) */}
      <div
        className="absolute inset-y-0 left-0 w-[3px] rounded-l-xl"
        style={{ background: 'var(--kpi-accent)' }}
        aria-hidden="true"
      />

      {/* Label + icon row */}
      <div className="mb-3 flex items-center justify-between">
        <span className="text-[10px] font-medium uppercase tracking-[0.06em] text-muted-foreground">
          {label}
        </span>
        {Icon && (
          <div
            className="flex h-8 w-8 items-center justify-center rounded-lg"
            style={{ background: 'color-mix(in oklch, var(--kpi-accent) 12%, transparent)' }}
          >
            <Icon
              className="h-4 w-4"
              style={{ color: 'var(--kpi-accent)' }}
              aria-hidden="true"
            />
          </div>
        )}
      </div>

      {/* Value */}
      {loading ? (
        <Skeleton className="h-8 w-24 mt-1" />
      ) : error ? (
        <div className="flex items-center gap-1.5 mt-1">
          <AlertCircle className="size-4 text-destructive" aria-hidden="true" />
          <span className="text-xs text-destructive">Failed to load</span>
        </div>
      ) : (
        <div className="text-[2rem] font-bold tabular-nums leading-none tracking-tight text-foreground">
          {value}
        </div>
      )}

      {/* Sparkline */}
      {sparkline && sparkline.length > 0 && (
        loading ? (
          <Skeleton className="h-12 w-full mt-2" />
        ) : (
          <div className="mt-2">
            <Sparkline
              data={sparkline}
              height={48}
              strokeColor={accentVar}
              fillColor={accentVar}
            />
          </div>
        )
      )}

      {/* Delta / trend */}
      {delta && !loading && !error && (
        <TrendBadge
          delta={delta}
          trend={trend}
          invertTrend={invertTrend}
          subtextLabel={subtextLabel}
        />
      )}
      {loading && !error && (
        <Skeleton className="h-4 w-16 mt-2.5" />
      )}
    </div>
  )

  if (href) {
    return <Link href={href}>{cardContent}</Link>
  }

  return cardContent
}

interface SparklineProps {
  data: number[]
  width?: number
  height?: number
  /** CSS color value or token reference — e.g. 'var(--color-primary)' */
  strokeColor?: string
  fillColor?: string
  strokeWidth?: number
  className?: string
}

/**
 * Inline SVG sparkline — line-only, area fill, last-point dot.
 * No external chart library. Sprint 1 design system primitive.
 */
export function Sparkline({
  data,
  width,
  height = 48,
  strokeColor = 'var(--color-primary)',
  fillColor = 'var(--color-primary)',
  strokeWidth = 1.5,
  className,
}: SparklineProps) {
  if (!data || data.length < 2) return null

  const min = Math.min(...data)
  const max = Math.max(...data)
  const range = max - min || 1

  // Use viewBox-relative coordinates; width is 100 units
  const W = 100
  const H = height
  const pad = 2

  const points = data.map((v, i) => ({
    x: (i / (data.length - 1)) * (W - pad * 2) + pad,
    y: H - pad - ((v - min) / range) * (H - pad * 2),
  }))

  const linePath = points
    .map((p, i) => `${i === 0 ? 'M' : 'L'} ${p.x.toFixed(2)} ${p.y.toFixed(2)}`)
    .join(' ')

  const areaPath = [
    linePath,
    `L ${points[points.length - 1].x.toFixed(2)} ${(H - pad).toFixed(2)}`,
    `L ${points[0].x.toFixed(2)} ${(H - pad).toFixed(2)}`,
    'Z',
  ].join(' ')

  const last = points[points.length - 1]
  const fillId = `sparkline-fill-${Math.random().toString(36).slice(2, 7)}`

  return (
    <svg
      viewBox={`0 0 ${W} ${H}`}
      preserveAspectRatio="none"
      aria-hidden="true"
      style={{ width: width ? `${width}px` : '100%', height: `${height}px`, display: 'block' }}
      className={className}
    >
      <defs>
        <linearGradient id={fillId} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={fillColor} stopOpacity="0.15" />
          <stop offset="100%" stopColor={fillColor} stopOpacity="0" />
        </linearGradient>
      </defs>

      {/* Area fill */}
      <path d={areaPath} fill={`url(#${fillId})`} />

      {/* Line */}
      <path
        d={linePath}
        fill="none"
        stroke={strokeColor}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
        style={{ opacity: 0.8 }}
      />

      {/* Last point dot */}
      <circle
        cx={last.x}
        cy={last.y}
        r={2.5}
        fill={strokeColor}
        style={{ opacity: 0.9 }}
      />
    </svg>
  )
}

import Link from 'next/link'
import { ArrowLeft, ChevronRight } from 'lucide-react'
import { cn } from '@/lib/utils'
import { Typography } from '@/components/ui/typography'
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from '@/components/ui/breadcrumb'

interface BreadcrumbItemDef {
  label: string
  href?: string // absent = current page (not a link)
}

interface PageHeaderProps {
  title: string
  description?: string         // replaces old `subtitle`
  actions?: React.ReactNode    // replaces old `right`
  breadcrumb?: BreadcrumbItemDef[]
  backHref?: string            // renders a back button/link before title
  className?: string
}

export function PageHeader({
  title,
  description,
  actions,
  breadcrumb,
  backHref,
  className,
}: PageHeaderProps) {
  return (
    <div
      className={cn(
        'flex flex-col gap-1 sm:flex-row sm:items-start sm:justify-between',
        className,
      )}
    >
      {/* Left column */}
      <div className="flex flex-col gap-1 min-w-0">
        {/* Back link */}
        {backHref && (
          <Link
            href={backHref}
            className="inline-flex items-center gap-1.5 text-sm text-muted-foreground hover:text-foreground transition-colors mb-1"
          >
            <ArrowLeft className="size-3.5" aria-hidden="true" />
            Back
          </Link>
        )}

        {/* Breadcrumb */}
        {breadcrumb && breadcrumb.length > 0 && (
          <Breadcrumb className="mb-2">
            <BreadcrumbList className="text-[13px]">
              {breadcrumb.map((item, i) => {
                const isLast = i === breadcrumb.length - 1
                return (
                  <BreadcrumbItem key={i}>
                    {isLast ? (
                      <BreadcrumbPage className="text-[13px]">{item.label}</BreadcrumbPage>
                    ) : (
                      <>
                        <BreadcrumbLink asChild>
                          <Link href={item.href ?? '#'} className="text-[13px]">
                            {item.label}
                          </Link>
                        </BreadcrumbLink>
                        <BreadcrumbSeparator>
                          <ChevronRight className="size-3" aria-hidden="true" />
                        </BreadcrumbSeparator>
                      </>
                    )}
                  </BreadcrumbItem>
                )
              })}
            </BreadcrumbList>
          </Breadcrumb>
        )}

        {/* Title */}
        <Typography variant="h1" className="truncate">
          {title}
        </Typography>

        {/* Description */}
        {description && (
          <Typography variant="body" className="text-muted-foreground mt-0.5">
            {description}
          </Typography>
        )}
      </div>

      {/* Actions slot */}
      {actions && (
        <div className="flex shrink-0 items-center gap-2 mt-4 sm:mt-0">
          {actions}
        </div>
      )}
    </div>
  )
}

import { cn } from '@/lib/utils'
import { Typography } from '@/components/ui/typography'

interface SectionProps {
  title?: string
  description?: string
  children: React.ReactNode
  className?: string
  /** Render title as this HTML heading level. Default: h2 */
  titleAs?: 'h2' | 'h3' | 'h4'
  /** Add a top border + label for settings-style annotated sections */
  annotated?: boolean
}

export function Section({
  title,
  description,
  children,
  className,
  titleAs = 'h2',
  annotated = false,
}: SectionProps) {
  if (annotated) {
    return (
      <section
        className={cn(
          'grid grid-cols-1 gap-6 border-t border-border pt-6 md:grid-cols-3',
          className,
        )}
      >
        <div className="md:col-span-1">
          {title && (
            <Typography variant="h3" as={titleAs}>
              {title}
            </Typography>
          )}
          {description && (
            <Typography variant="caption" className="mt-1">
              {description}
            </Typography>
          )}
        </div>
        <div className="md:col-span-2 space-y-4">{children}</div>
      </section>
    )
  }

  return (
    <section className={cn('space-y-4', className)}>
      {(title ?? description) && (
        <header className="space-y-1">
          {title && (
            <Typography variant="h3" as={titleAs}>
              {title}
            </Typography>
          )}
          {description && (
            <Typography variant="body-sm" className="text-muted-foreground">
              {description}
            </Typography>
          )}
        </header>
      )}
      {children}
    </section>
  )
}

import type { LucideIcon } from 'lucide-react'
