'use client'

import {
  useReactTable,
  getCoreRowModel,
  getSortedRowModel,
  getPaginationRowModel,
  flexRender,
  type ColumnDef,
  type SortingState,
  type RowSelectionState,
  type PaginationState,
  type OnChangeFn,
} from '@tanstack/react-table'
import { ChevronUp, ChevronDown, ChevronLeft, ChevronRight, ChevronsUpDown, Table2 } from 'lucide-react'
import { cn } from '@/lib/utils'
import { Button } from '@/components/ui/button'
import { Checkbox } from '@/components/ui/checkbox'
import { Skeleton } from '@/components/ui/skeleton'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { EmptyState } from '@/components/shared/EmptyState'

interface DataTableProps<TData> {
  columns: ColumnDef<TData>[]
  data: TData[]
  loading?: boolean
  /** Total row count (server-side). If absent, client-side pagination. */
  rowCount?: number
  sorting?: SortingState
  onSortingChange?: OnChangeFn<SortingState>
  pagination?: PaginationState
  onPaginationChange?: OnChangeFn<PaginationState>
  rowSelection?: RowSelectionState
  onRowSelectionChange?: OnChangeFn<RowSelectionState>
  /** Page sizes to offer. Default: [10, 25, 50] */
  pageSizeOptions?: number[]
  caption?: string
  /** If provided, renders above the table */
  filterBar?: React.ReactNode
  emptyState?: React.ReactNode
  className?: string
}

export type { ColumnDef }

export function DataTable<TData>({
  columns,
  data,
  loading = false,
  rowCount,
  sorting,
  onSortingChange,
  pagination,
  onPaginationChange,
  rowSelection,
  onRowSelectionChange,
  pageSizeOptions = [10, 25, 50],
  caption,
  filterBar,
  emptyState,
  className,
}: DataTableProps<TData>) {
  const hasSelection = Boolean(onRowSelectionChange)

  const allColumns: ColumnDef<TData>[] = [
    ...(hasSelection
      ? [
          {
            id: '__select__',
            header: ({ table }: Parameters<NonNullable<ColumnDef<TData>['header']>>[0]) => (
              <Checkbox
                checked={
                  table.getIsAllPageRowsSelected()
                    ? true
                    : table.getIsSomePageRowsSelected()
                      ? 'indeterminate'
                      : false
                }
                onCheckedChange={(v) => table.toggleAllPageRowsSelected(!!v)}
                aria-label="Select all"
              />
            ),
            cell: ({ row }: Parameters<NonNullable<ColumnDef<TData>['cell']>>[0]) => (
              <Checkbox
                checked={row.getIsSelected()}
                onCheckedChange={(v) => row.toggleSelected(!!v)}
                aria-label={`Select row ${row.index + 1}`}
              />
            ),
            size: 40,
            enableSorting: false,
            enableHiding: false,
          } satisfies ColumnDef<TData>,
        ]
      : []),
    ...columns,
  ]

  const table = useReactTable({
    data,
    columns: allColumns,
    state: {
      ...(sorting !== undefined ? { sorting } : {}),
      ...(pagination !== undefined ? { pagination } : {}),
      ...(rowSelection !== undefined ? { rowSelection } : {}),
    },
    manualPagination: rowCount !== undefined,
    manualSorting: onSortingChange !== undefined,
    rowCount,
    onSortingChange,
    onPaginationChange,
    onRowSelectionChange,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    enableRowSelection: hasSelection,
  })

  const currentPage = table.getState().pagination.pageIndex
  const pageSize = table.getState().pagination.pageSize
  const totalRows = rowCount ?? data.length
  const totalPages = Math.max(1, Math.ceil(totalRows / pageSize))

  const startRow = currentPage * pageSize + 1
  const endRow = Math.min(startRow + pageSize - 1, totalRows)

  return (
    <div className={cn('space-y-3', className)}>
      {/* FilterBar slot */}
      {filterBar && <div>{filterBar}</div>}

      {/* Desktop table */}
      <div className="hidden md:block rounded-xl border border-border/50 bg-card shadow-[var(--shadow-card)] overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm" aria-label={caption}>
            <thead>
              {table.getHeaderGroups().map((headerGroup) => (
                <tr key={headerGroup.id} className="border-b border-border/40 bg-muted/20">
                  {headerGroup.headers.map((header) => {
                    const canSort = header.column.getCanSort()
                    const sorted = header.column.getIsSorted()
                    return (
                      <th
                        key={header.id}
                        className={cn(
                          'h-10 px-4 text-left align-middle first:pl-5 last:pr-5',
                          canSort && 'cursor-pointer select-none hover:text-foreground',
                        )}
                        onClick={canSort ? header.column.getToggleSortingHandler() : undefined}
                        style={{ width: header.getSize() !== 150 ? header.getSize() : undefined }}
                      >
                        <div className="flex items-center gap-1">
                          <span className="text-[11px] font-semibold uppercase tracking-widest text-muted-foreground/70">
                            {header.isPlaceholder
                              ? null
                              : flexRender(header.column.columnDef.header, header.getContext())}
                          </span>
                          {canSort && (
                            <span className="text-muted-foreground/50">
                              {sorted === 'asc' ? (
                                <ChevronUp className="size-3.5" aria-hidden="true" />
                              ) : sorted === 'desc' ? (
                                <ChevronDown className="size-3.5" aria-hidden="true" />
                              ) : (
                                <ChevronsUpDown className="size-3.5" aria-hidden="true" />
                              )}
                            </span>
                          )}
                        </div>
                      </th>
                    )
                  })}
                </tr>
              ))}
            </thead>
            <tbody>
              {loading ? (
                Array.from({ length: Math.min(pageSize, 5) }).map((_, i) => (
                  <tr key={i} className="border-b border-border/30 last:border-0">
                    {allColumns.map((_, j) => (
                      <td key={j} className="h-12 px-4 first:pl-5 last:pr-5">
                        <Skeleton className="h-3 w-full" />
                      </td>
                    ))}
                  </tr>
                ))
              ) : table.getRowModel().rows.length === 0 ? (
                <tr>
                  <td colSpan={allColumns.length}>
                    {emptyState ?? (
                      <EmptyState
                        icon={Table2}
                        title="No results"
                        description="No data matches the current filters."
                        variant="filtered"
                      />
                    )}
                  </td>
                </tr>
              ) : (
                table.getRowModel().rows.map((row) => (
                  <tr
                    key={row.id}
                    className={cn(
                      'border-b border-border/30 last:border-0 transition-colors',
                      'hover:bg-muted/30',
                      row.getIsSelected() && 'bg-accent/30',
                    )}
                  >
                    {row.getVisibleCells().map((cell) => (
                      <td
                        key={cell.id}
                        className="h-12 px-4 align-middle first:pl-5 last:pr-5"
                      >
                        {flexRender(cell.column.columnDef.cell, cell.getContext())}
                      </td>
                    ))}
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        {/* Pagination footer */}
        <div className="flex items-center justify-between border-t border-border/40 px-5 py-3 gap-4 flex-wrap">
          <p className="text-xs text-muted-foreground tabular-nums">
            {loading
              ? 'Loading...'
              : totalRows === 0
                ? '0 rows'
                : `Showing ${startRow}–${endRow} of ${totalRows.toLocaleString()} rows`}
          </p>
          <div className="flex items-center gap-3">
            {/* Page size */}
            <div className="flex items-center gap-1.5">
              <span className="text-xs text-muted-foreground">Rows</span>
              <Select
                value={String(pageSize)}
                onValueChange={(v) => table.setPageSize(Number(v))}
              >
                <SelectTrigger className="h-7 w-16 text-xs">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {pageSizeOptions.map((size) => (
                    <SelectItem key={size} value={String(size)} className="text-xs">
                      {size}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Navigation */}
            <span className="text-xs text-muted-foreground tabular-nums">
              Page {currentPage + 1} of {totalPages}
            </span>
            <div className="flex gap-1">
              <Button
                variant="outline"
                size="icon"
                className="size-8"
                disabled={!table.getCanPreviousPage() || loading}
                onClick={() => table.previousPage()}
                aria-label="Previous page"
              >
                <ChevronLeft className="size-4" />
              </Button>
              <Button
                variant="outline"
                size="icon"
                className="size-8"
                disabled={!table.getCanNextPage() || loading}
                onClick={() => table.nextPage()}
                aria-label="Next page"
              >
                <ChevronRight className="size-4" />
              </Button>
            </div>
          </div>
        </div>
      </div>

      {/* Mobile card list (< md) */}
      <div className="md:hidden space-y-2">
        {loading ? (
          Array.from({ length: 3 }).map((_, i) => (
            <div key={i} className="rounded-xl border border-border/50 bg-card p-4 space-y-2">
              <Skeleton className="h-4 w-3/4" />
              <Skeleton className="h-3 w-1/2" />
              <Skeleton className="h-3 w-2/3" />
            </div>
          ))
        ) : table.getRowModel().rows.length === 0 ? (
          emptyState ?? (
            <EmptyState
              icon={Table2}
              title="No results"
              description="No data matches the current filters."
              variant="filtered"
            />
          )
        ) : (
          table.getRowModel().rows.map((row) => {
            const cells = row.getVisibleCells().filter(
              (c) => c.column.id !== '__select__',
            )
            const [primaryCell, ...restCells] = cells

            return (
              <div
                key={row.id}
                className={cn(
                  'rounded-xl border border-border/50 bg-card p-4 space-y-2',
                  row.getIsSelected() && 'border-primary/30 bg-accent/20',
                )}
              >
                {/* Primary identity */}
                {primaryCell && (
                  <div className="font-medium text-sm text-foreground">
                    {flexRender(primaryCell.column.columnDef.cell, primaryCell.getContext())}
                  </div>
                )}

                {/* Remaining label:value pairs */}
                {restCells.slice(0, -1).map((cell) => {
                  const headerDef = cell.column.columnDef.header
                  const headerLabel =
                    typeof headerDef === 'string'
                      ? headerDef
                      : (cell.column.columnDef.meta as { mobileLabel?: string } | undefined)?.mobileLabel ??
                        cell.column.id

                  return (
                    <div key={cell.id} className="flex items-center justify-between text-xs">
                      <span className="text-muted-foreground">{headerLabel}</span>
                      <span className="text-foreground">
                        {flexRender(cell.column.columnDef.cell, cell.getContext())}
                      </span>
                    </div>
                  )
                })}

                {/* Last cell (actions) */}
                {restCells.length > 0 && (
                  <div className="pt-1">
                    {flexRender(
                      restCells[restCells.length - 1].column.columnDef.cell,
                      restCells[restCells.length - 1].getContext(),
                    )}
                  </div>
                )}
              </div>
            )
          })
        )}

        {/* Mobile pagination */}
        {totalPages > 1 && !loading && (
          <div className="flex items-center justify-between pt-2">
            <span className="text-xs text-muted-foreground">
              Page {currentPage + 1} of {totalPages}
            </span>
            <div className="flex gap-1">
              <Button
                variant="outline"
                size="icon"
                className="size-8"
                disabled={!table.getCanPreviousPage()}
                onClick={() => table.previousPage()}
                aria-label="Previous page"
              >
                <ChevronLeft className="size-4" />
              </Button>
              <Button
                variant="outline"
                size="icon"
                className="size-8"
                disabled={!table.getCanNextPage()}
                onClick={() => table.nextPage()}
                aria-label="Next page"
              >
                <ChevronRight className="size-4" />
              </Button>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

