'use client'

import { useState, useCallback } from 'react'
import type { LucideIcon } from 'lucide-react'
import { Check, ChevronsUpDown, Loader2, X } from 'lucide-react'
import { cn } from '@/lib/utils'
import { Button } from '@/components/ui/button'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/components/ui/command'

export interface ComboBoxOption {
  value: string
  label: string
  description?: string
  icon?: LucideIcon
}

interface ComboBoxProps {
  options: ComboBoxOption[]
  value: string | null
  onValueChange: (value: string | null) => void
  placeholder?: string
  searchPlaceholder?: string
  /** Async search — if provided, options are loaded on query change */
  onSearch?: (query: string) => Promise<ComboBoxOption[]>
  loading?: boolean
  disabled?: boolean
  className?: string
}

export function ComboBox({
  options: initialOptions,
  value,
  onValueChange,
  placeholder = 'Select...',
  searchPlaceholder = 'Search...',
  onSearch,
  loading = false,
  disabled = false,
  className,
}: ComboBoxProps) {
  const [open, setOpen] = useState(false)
  const [asyncOptions, setAsyncOptions] = useState<ComboBoxOption[]>([])
  const [searching, setSearching] = useState(false)

  const options = onSearch ? asyncOptions : initialOptions
  const selectedOption = [...initialOptions, ...asyncOptions].find((o) => o.value === value)

  const handleSearch = useCallback(
    async (query: string) => {
      if (!onSearch) return
      setSearching(true)
      try {
        const results = await onSearch(query)
        setAsyncOptions(results)
      } finally {
        setSearching(false)
      }
    },
    [onSearch],
  )

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          role="combobox"
          aria-expanded={open}
          disabled={disabled || loading}
          className={cn('w-full justify-between font-normal', className)}
        >
          <span className={cn(!selectedOption && 'text-muted-foreground')}>
            {selectedOption?.label ?? placeholder}
          </span>
          <div className="flex items-center gap-0.5">
            {value && (
              <span
                role="button"
                tabIndex={0}
                onClick={(e) => {
                  e.stopPropagation()
                  onValueChange(null)
                }}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' || e.key === ' ') {
                    e.stopPropagation()
                    onValueChange(null)
                  }
                }}
                className="flex items-center rounded-sm p-0.5 opacity-60 hover:opacity-100"
                aria-label="Clear selection"
              >
                <X className="size-3" />
              </span>
            )}
            <ChevronsUpDown className="size-4 opacity-50" aria-hidden="true" />
          </div>
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-(--anchor-width) p-0" align="start">
        <Command>
          <CommandInput
            placeholder={searchPlaceholder}
            onValueChange={onSearch ? handleSearch : undefined}
          />
          <CommandList>
            {(searching || loading) ? (
              <CommandEmpty className="py-4 flex justify-center">
                <Loader2 className="size-4 animate-spin text-muted-foreground" aria-hidden="true" />
              </CommandEmpty>
            ) : (
              <CommandEmpty className="py-4 text-center text-xs text-muted-foreground">
                No results found.
              </CommandEmpty>
            )}
            <CommandGroup>
              {options.map((opt) => {
                const Icon = opt.icon
                return (
                  <CommandItem
                    key={opt.value}
                    value={opt.value}
                    onSelect={(v) => {
                      onValueChange(v === value ? null : v)
                      setOpen(false)
                    }}
                  >
                    <Check
                      className={cn(
                        'mr-2 size-4',
                        value === opt.value ? 'opacity-100' : 'opacity-0',
                      )}
                      aria-hidden="true"
                    />
                    {Icon && (
                      <Icon className="mr-2 size-4 text-muted-foreground" aria-hidden="true" />
                    )}
                    <div className="flex flex-col">
                      <span>{opt.label}</span>
                      {opt.description && (
                        <span className="text-xs text-muted-foreground">{opt.description}</span>
                      )}
                    </div>
                  </CommandItem>
                )
              })}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  )
}

'use client'

import { useState } from 'react'
import { format, startOfDay, endOfDay, startOfMonth, endOfMonth, subDays, startOfQuarter, endOfQuarter } from 'date-fns'
import { CalendarDays, ChevronDown } from 'lucide-react'
import { cn } from '@/lib/utils'
import { Button } from '@/components/ui/button'
import { Calendar } from '@/components/ui/calendar'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import type { DateRange as CalendarDateRange } from 'react-day-picker'

export interface DateRange {
  from: Date | undefined
  to: Date | undefined
}

interface Preset {
  label: string
  range: DateRange
}

interface DateRangePickerProps {
  value: DateRange
  onValueChange: (range: DateRange) => void
  placeholder?: string
  presets?: Preset[]
  disabled?: boolean
  className?: string
}

function buildDefaultPresets(): Preset[] {
  const today = new Date()
  const yesterday = subDays(today, 1)
  return [
    {
      label: 'Today',
      range: { from: startOfDay(today), to: endOfDay(today) },
    },
    {
      label: 'Yesterday',
      range: { from: startOfDay(yesterday), to: endOfDay(yesterday) },
    },
    {
      label: 'Last 7 days',
      range: { from: startOfDay(subDays(today, 6)), to: endOfDay(today) },
    },
    {
      label: 'Last 30 days',
      range: { from: startOfDay(subDays(today, 29)), to: endOfDay(today) },
    },
    {
      label: 'This month',
      range: { from: startOfMonth(today), to: endOfDay(today) },
    },
    {
      label: 'Last month',
      range: {
        from: startOfMonth(subDays(startOfMonth(today), 1)),
        to: endOfMonth(subDays(startOfMonth(today), 1)),
      },
    },
    {
      label: 'Last 3 months',
      range: { from: startOfDay(subDays(today, 89)), to: endOfDay(today) },
    },
  ]
}

export function DateRangePicker({
  value,
  onValueChange,
  placeholder = 'Pick a date range',
  presets,
  disabled = false,
  className,
}: DateRangePickerProps) {
  const [open, setOpen] = useState(false)
  const [draft, setDraft] = useState<DateRange>(value)

  const resolvedPresets = presets ?? buildDefaultPresets()

  function formatRange(range: DateRange): string {
    if (!range.from) return placeholder
    if (!range.to) return format(range.from, 'MMM d, yyyy')
    return `${format(range.from, 'MMM d, yyyy')} – ${format(range.to, 'MMM d, yyyy')}`
  }

  function handleCalendarSelect(sel: CalendarDateRange | undefined) {
    setDraft({ from: sel?.from, to: sel?.to })
  }

  function handleApply() {
    onValueChange(draft)
    setOpen(false)
  }

  function handleCancel() {
    setDraft(value)
    setOpen(false)
  }

  function handlePreset(preset: Preset) {
    setDraft(preset.range)
  }

  return (
    <Popover open={open} onOpenChange={(v) => { if (!v) handleCancel(); else setOpen(v) }}>
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          disabled={disabled}
          className={cn(
            'justify-start gap-2 font-normal',
            !value.from && 'text-muted-foreground',
            className,
          )}
        >
          <CalendarDays className="size-4 shrink-0" aria-hidden="true" />
          <span className="flex-1 text-left">{formatRange(value)}</span>
          <ChevronDown className="size-4 opacity-50 shrink-0" aria-hidden="true" />
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-auto p-0 flex" align="start">
        {/* Preset list */}
        <div className="w-36 border-r border-border py-2 shrink-0">
          {resolvedPresets.map((preset) => (
            <button
              key={preset.label}
              type="button"
              onClick={() => handlePreset(preset)}
              className="w-full px-3 py-1.5 text-left text-xs hover:bg-accent hover:text-accent-foreground transition-colors"
            >
              {preset.label}
            </button>
          ))}
        </div>

        {/* Calendar */}
        <div className="p-3">
          <Calendar
            mode="range"
            selected={{ from: draft.from, to: draft.to }}
            onSelect={handleCalendarSelect}
            numberOfMonths={2}
            defaultMonth={draft.from}
          />

          {/* Footer */}
          <div className="flex justify-end gap-2 pt-2 border-t border-border mt-2">
            <Button variant="ghost" size="sm" onClick={handleCancel}>
              Cancel
            </Button>
            <Button size="sm" onClick={handleApply} disabled={!draft.from}>
              Apply
            </Button>
          </div>
        </div>
      </PopoverContent>
    </Popover>
  )
}

'use client'

import { useCallback, useRef } from 'react'
import { Minus, Plus } from 'lucide-react'
import { cn } from '@/lib/utils'

interface NumberInputProps {
  value: number | undefined
  onValueChange: (value: number | undefined) => void
  min?: number
  max?: number
  step?: number
  precision?: number
  placeholder?: string
  disabled?: boolean
  className?: string
}

export function NumberInput({
  value,
  onValueChange,
  min,
  max,
  step = 1,
  precision = 0,
  placeholder,
  disabled = false,
  className,
}: NumberInputProps) {
  const inputRef = useRef<HTMLInputElement>(null)

  function clamp(n: number): number {
    let result = n
    if (min !== undefined) result = Math.max(min, result)
    if (max !== undefined) result = Math.min(max, result)
    return parseFloat(result.toFixed(precision))
  }

  function handleDecrement() {
    const next = clamp((value ?? 0) - step)
    onValueChange(next)
  }

  function handleIncrement() {
    const next = clamp((value ?? 0) + step)
    onValueChange(next)
  }

  function handleChange(e: React.ChangeEvent<HTMLInputElement>) {
    const raw = e.target.value
    if (raw === '' || raw === '-') {
      onValueChange(undefined)
      return
    }
    const n = parseFloat(raw)
    if (!isNaN(n)) {
      onValueChange(clamp(n))
    }
  }

  function handleKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
    if (e.key === 'ArrowUp') {
      e.preventDefault()
      handleIncrement()
    } else if (e.key === 'ArrowDown') {
      e.preventDefault()
      handleDecrement()
    }
  }

  const atMin = min !== undefined && value !== undefined && value <= min
  const atMax = max !== undefined && value !== undefined && value >= max

  return (
    <div
      className={cn(
        'flex items-center rounded-md border border-input bg-background focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-0 transition-shadow',
        disabled && 'opacity-50 cursor-not-allowed',
        className,
      )}
    >
      <input
        ref={inputRef}
        type="number"
        value={value ?? ''}
        onChange={handleChange}
        onKeyDown={handleKeyDown}
        placeholder={placeholder}
        disabled={disabled}
        min={min}
        max={max}
        step={step}
        className="flex-1 bg-transparent px-3 py-2 text-sm tabular-nums outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
      />
      <div className="flex flex-col border-l border-input shrink-0">
        <button
          type="button"
          onClick={handleIncrement}
          disabled={disabled || atMax}
          className="flex h-5 w-8 items-center justify-center text-muted-foreground hover:text-foreground hover:bg-muted/50 transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
          aria-label="Increment"
          tabIndex={-1}
        >
          <Plus className="size-3" />
        </button>
        <button
          type="button"
          onClick={handleDecrement}
          disabled={disabled || atMin}
          className="flex h-5 w-8 items-center justify-center border-t border-input text-muted-foreground hover:text-foreground hover:bg-muted/50 transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
          aria-label="Decrement"
          tabIndex={-1}
        >
          <Minus className="size-3" />
        </button>
      </div>
    </div>
  )
}

