import { useState } from 'react'
import { parsePhoneNumber, isValidPhoneNumber, getCountries, getCountryCallingCode } from 'libphonenumber-js'
import type { CountryCode } from 'libphonenumber-js'
import { cn } from '@/lib/utils'
import { ComboBox } from '@/components/ui/combobox'
import { Input } from '@/components/ui/input'

interface PhoneInputProps {
  value: string
  onValueChange: (value: string) => void
  defaultCountry?: CountryCode
  placeholder?: string
  disabled?: boolean
  className?: string
}

// Build sorted country list (all ISO 3166-1 alpha-2 with calling codes)
function buildCountryOptions() {
  return getCountries()
    .map((code) => {
      try {
        const calling = getCountryCallingCode(code)
        return {
          value: code,
          label: `${code} +${calling}`,
          description: `+${calling}`,
        }
      } catch {
        return null
      }
    })
    .filter((c): c is NonNullable<typeof c> => c !== null)
    .sort((a, b) => a.value.localeCompare(b.value))
}

const countryOptions = buildCountryOptions()

function getFlag(countryCode: string): string {
  // Use regional indicator symbols to render flag emoji
  return countryCode
    .toUpperCase()
    .split('')
    .map((c) => String.fromCodePoint(0x1f1e6 + c.charCodeAt(0) - 65))
    .join('')
}

export function PhoneInput({
  value,
  onValueChange,
  defaultCountry = 'US',
  placeholder = 'Phone number',
  disabled = false,
  className,
}: PhoneInputProps) {
  const [country, setCountry] = useState<CountryCode>(defaultCountry)

  // Parse out local number from E.164 value if present
  function getLocalNumber(): string {
    if (!value) return ''
    try {
      const parsed = parsePhoneNumber(value, country)
      if (parsed) return parsed.formatNational()
    } catch {
      // not a full E.164 yet
    }
    return value
  }

  function handleLocalChange(e: React.ChangeEvent<HTMLInputElement>) {
    const local = e.target.value
    if (!local) {
      onValueChange('')
      return
    }
    try {
      const calling = getCountryCallingCode(country)
      const full = `+${calling}${local.replace(/\D/g, '')}`
      if (isValidPhoneNumber(full, country)) {
        const parsed = parsePhoneNumber(full, country)
        onValueChange(parsed.format('E.164'))
      } else {
        onValueChange(full)
      }
    } catch {
      onValueChange(local)
    }
  }

  function handleCountryChange(val: string | null) {
    if (val) setCountry(val as CountryCode)
  }

  const flag = getFlag(country)
  let callingCode = ''
  try {
    callingCode = `+${getCountryCallingCode(country)}`
  } catch {
    callingCode = ''
  }

  return (
    <div
      className={cn(
        'flex items-center rounded-md border border-input bg-background focus-within:ring-2 focus-within:ring-ring transition-shadow',
        disabled && 'opacity-50 cursor-not-allowed',
        className,
      )}
    >
      {/* Country selector */}
      <div className="shrink-0 border-r border-input">
        <ComboBox
          options={countryOptions}
          value={country}
          onValueChange={handleCountryChange}
          placeholder={`${flag} ${callingCode}`}
          searchPlaceholder="Search country..."
          disabled={disabled}
          className="h-9 border-0 rounded-r-none rounded-l-md shadow-none focus:ring-0 w-28 gap-1"
        />
      </div>

      {/* Number input */}
      <Input
        type="tel"
        value={getLocalNumber()}
        onChange={handleLocalChange}
        placeholder={placeholder}
        disabled={disabled}
        className="border-0 rounded-l-none shadow-none focus-visible:ring-0 flex-1"
      />
    </div>
  )
}

