import { useState, useRef } from 'react'
import { cn } from '@/lib/utils'

interface MoneyInputProps {
  value: number | undefined         // value in cents (integer)
  onValueChange: (cents: number | undefined) => void
  currency?: string                  // ISO 4217, default: 'USD'
  locale?: string                    // default: 'en-US'
  placeholder?: string
  disabled?: boolean
  className?: string
}

function getCurrencySymbol(currency: string, locale: string): string {
  try {
    return new Intl.NumberFormat(locale, { style: 'currency', currency, currencyDisplay: 'symbol' })
      .formatToParts(0)
      .find((p) => p.type === 'currency')?.value ?? currency
  } catch {
    return currency
  }
}

function centsToDisplay(cents: number | undefined, precision: number): string {
  if (cents === undefined) return ''
  return (cents / Math.pow(10, precision)).toFixed(precision)
}

function displayToCents(display: string, precision: number): number | undefined {
  const n = parseFloat(display.replace(/,/g, ''))
  if (isNaN(n)) return undefined
  return Math.round(n * Math.pow(10, precision))
}

export function MoneyInput({
  value,
  onValueChange,
  currency = 'USD',
  locale = 'en-US',
  placeholder = '0.00',
  disabled = false,
  className,
}: MoneyInputProps) {
  const precision = 2
  const symbol = getCurrencySymbol(currency, locale)
  const [display, setDisplay] = useState<string>(centsToDisplay(value, precision) ?? '')
  const inputRef = useRef<HTMLInputElement>(null)

  function handleChange(e: React.ChangeEvent<HTMLInputElement>) {
    const raw = e.target.value
    // Allow only digits, decimal point, minus
    if (/^-?\d*\.?\d*$/.test(raw) || raw === '') {
      setDisplay(raw)
      onValueChange(displayToCents(raw, precision))
    }
  }

  function handleBlur() {
    if (display !== '') {
      const cents = displayToCents(display, precision)
      if (cents !== undefined) {
        setDisplay(centsToDisplay(cents, precision) ?? '')
      }
    }
  }

  return (
    <div
      className={cn(
        'flex items-center rounded-md border border-input bg-background focus-within:ring-2 focus-within:ring-ring transition-shadow',
        disabled && 'opacity-50 cursor-not-allowed',
        className,
      )}
      onClick={() => inputRef.current?.focus()}
    >
      {/* Currency symbol prefix */}
      <div className="flex items-center px-3 border-r border-input bg-muted/30 rounded-l-md self-stretch">
        <span className="text-sm text-muted-foreground tabular-nums select-none">
          {symbol}
        </span>
      </div>

      {/* Number input */}
      <input
        ref={inputRef}
        type="text"
        inputMode="decimal"
        value={display}
        onChange={handleChange}
        onBlur={handleBlur}
        placeholder={placeholder}
        disabled={disabled}
        className="flex-1 bg-transparent px-3 py-2 text-sm tabular-nums outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed"
      />
    </div>
  )
}

