import { useCallback } from 'react'
import { useDropzone } from 'react-dropzone'
import { UploadCloud, Loader2 } from 'lucide-react'
import { cn } from '@/lib/utils'
import { Typography } from '@/components/ui/typography'

interface FileRejection {
  file: File
  errors: string[]
}

interface FileDropzoneProps {
  accept?: Record<string, string[]>  // react-dropzone format
  maxSize?: number                    // bytes, default: 5MB
  maxFiles?: number                   // default: 1
  onFilesAccepted: (files: File[]) => void
  onFilesRejected?: (errors: FileRejection[]) => void
  loading?: boolean
  disabled?: boolean
  children?: React.ReactNode  // custom content
  className?: string
}

const DEFAULT_MAX_SIZE = 5 * 1024 * 1024 // 5MB

function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes}B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(0)}KB`
  return `${(bytes / (1024 * 1024)).toFixed(0)}MB`
}

function formatAccept(accept: Record<string, string[]> | undefined): string {
  if (!accept) return 'All files'
  const exts = Object.values(accept).flat().join(', ')
  return exts || 'All files'
}

export function FileDropzone({
  accept,
  maxSize = DEFAULT_MAX_SIZE,
  maxFiles = 1,
  onFilesAccepted,
  onFilesRejected,
  loading = false,
  disabled = false,
  children,
  className,
}: FileDropzoneProps) {
  const onDrop = useCallback(
    (accepted: File[], rejected: import('react-dropzone').FileRejection[]) => {
      if (accepted.length) onFilesAccepted(accepted)
      if (rejected.length && onFilesRejected) {
        onFilesRejected(
          rejected.map((r) => ({
            file: r.file,
            errors: r.errors.map((e) => e.message),
          })),
        )
      }
    },
    [onFilesAccepted, onFilesRejected],
  )

  const { getRootProps, getInputProps, isDragActive, isDragReject } = useDropzone({
    accept,
    maxSize,
    maxFiles,
    onDrop,
    disabled: disabled || loading,
  })

  return (
    <div
      {...getRootProps()}
      className={cn(
        'flex flex-col items-center justify-center rounded-xl border-2 border-dashed transition-colors cursor-pointer p-8 text-center',
        !isDragActive && !isDragReject && 'border-border bg-muted/20 hover:border-primary/40 hover:bg-muted/40',
        isDragActive && !isDragReject && 'border-primary bg-primary/5',
        isDragReject && 'border-destructive bg-destructive/5',
        (disabled || loading) && 'opacity-50 cursor-not-allowed',
        className,
      )}
    >
      <input {...getInputProps()} />

      {children ?? (
        loading ? (
          <Loader2 className="size-8 animate-spin text-primary" aria-hidden="true" />
        ) : (
          <>
            <UploadCloud
              className={cn(
                'size-10 mb-3',
                isDragReject ? 'text-destructive/70' : 'text-muted-foreground/50',
              )}
              aria-hidden="true"
            />
            <Typography variant="body-sm" className="font-medium">
              {isDragActive
                ? isDragReject
                  ? 'File not accepted'
                  : 'Drop files here'
                : 'Drag files here, or click to browse'}
            </Typography>
            <Typography variant="caption" className="mt-1">
              {formatAccept(accept)} · Max {formatBytes(maxSize)}
            </Typography>
          </>
        )
      )}
    </div>
  )
}

import type { FieldValues, Path, Control, ControllerRenderProps } from 'react-hook-form'
